derived-channel.expr:
{
	connection = $project.get(`tl.factory:Project#gitConnection`);
	if($connection == null, null, {
		kind = if(factoryGitBuiltIn($connection), #('built-in'@en, 'eingebaut'@de), #('own connection of the tenant'@en, 'eigene Verbindung des Mandanten'@de));
		{{{<p>{#('Git connection'@en, 'Git-Verbindung'@de)}: {$connection.get(`tl.factory:GitConnection#name`)} ({$kind})</p>}}};
	});
}
